    "slug": "five-affordable-omega-speedmaster-moonwatch-alternatives",
    "title": "Five Affordable Omega Speedmaster Moonwatch Alternatives",
    "category": "Omega & Koleksiyon",
    "publish_date": "25 Mayıs 2026",
    "raw_date": "2026-05-25",
    "author": "Belgin Saat & Mücevherat Editoryal Kurulu",
